/* Constants */
export const AAC_BITRATES_KBPS = [128,192,256,320] as const;

export const AUTO_BACKUP_KEEP = 7 as const;

export const DEFAULT_AAC_BITRATE_KBPS = 256 as const;

export const DEFAULT_ACCENT_COLOR = "#3b82f6" as const;

export const DEFAULT_MUSIC_FOLDER_TEMPLATE = "%albumartist%/%album%/[%disc%-]%track% %title%" as const;

export const LIBRARY_SCAN_INTERVALS = [0,15,30,60,360] as const;

export const MAX_CROSSFADE_SECONDS = 12 as const;

export const MAX_NORMALIZATION_PREAMP_DB = 12 as const;

/* Types */
/**  トラックのアルバムアートの情報（アルバムアートの画面に出す） */
export type AlbumArtInfo = {
	source: AlbumArtSource,
	/**  フォルダの画像のファイル名（埋め込みの画像ではNone） */
	fileName: string | null,
	/**  MIMEタイプ（image/jpeg, image/png など） */
	mimeType: string,
	/**  画像データのサイズ（バイト） */
	size: number,
	/**  幅・高さ（ピクセル。読めない場合はNone） */
	width: number | null,
	height: number | null,
};

/**  表示しているアルバムアートが、どこの画像か */
export type AlbumArtSource = 
/**  音楽ファイルに埋め込まれた画像 */
"embedded" | 
/**  音楽ファイルと同じフォルダの画像（`cover.jpg`など） */
"folder";

/**  アルバムとその曲（アーティストの詳細で、アルバムごとに曲を表示するために使う） */
export type AlbumGroup = {
	name: string,
	/**  並び順に使う値（`AlbumSummary::sort_name`と同じ） */
	sortName: string | null,
	artist: string | null,
	trackCount: number,
	totalDuration: number,
	representativeTrackId: string,
	tracks: Track[],
};

/**
 *  アルバムの一覧の1件（曲は含めない。曲は`get_album_tracks`で取得する）
 * 
 *  アルバムは「アルバムアーティスト（なければ曲のアーティスト）＋アルバム名」でまとめる。
 */
export type AlbumSummary = {
	name: string,
	/**  並び順に使う値（アルバムの曲のソート用のタグ。なければ値なしで、`name`で並べる） */
	sortName: string | null,
	/**  アルバムをまとめたアーティスト（アルバムアーティスト。なければ曲のアーティスト） */
	artist: string | null,
	trackCount: number,
	totalDuration: number,
	representativeTrackId: string,
};

/**
 *  アプリケーション全体で使用するエラー型
 * 
 *  serdeのadjacently tagged表現により `{ "code": "LOCK", "message": "..." }`
 *  形式でシリアライズされる。specta::Typeによりコードのリテラル型union
 *  としてTypeScriptへエクスポートされる。
 */
export type AppError = 
/**  ロック取得の失敗（DBロック・ステートロック） */
{ code: "LOCK"; message: string } | 
/**  データベース操作の失敗 */
{ code: "DATABASE"; message: string } | 
/**  対象（トラック・プレイリスト・ファイル等）が見つからない */
{ code: "NOT_FOUND"; message: string } | 
/**  入力バリデーションエラー */
{ code: "VALIDATION"; message: string } | 
/**  ファイルI/Oエラー */
{ code: "IO"; message: string } | 
/**  メタデータの抽出・書き込みエラー */
{ code: "METADATA"; message: string } | 
/**  再生エンジンのエラー（デコードできない・出力デバイスを使えない） */
{ code: "PLAYBACK"; message: string };

/**
 *  アーティストの一覧の1件（アルバムと曲は含めない。`get_artist_albums`で取得する）
 * 
 *  アーティストは、アルバムアーティスト（なければ曲のアーティスト）でまとめる。
 */
export type ArtistSummary = {
	name: string,
	/**  並び順に使う値（アーティストの曲のソート用のタグ。なければ値なしで、`name`で並べる） */
	sortName: string | null,
	albumCount: number,
	trackCount: number,
	totalDuration: number,
	representativeTrackId: string,
};

/**  バックアップを保存した結果 */
export type BackupSaved = {
	/**  保存したファイル */
	path: string,
	trackCount: number,
	playlistCount: number,
};

/**  一括編集の結果 */
export type BulkUpdateResult = {
	/**  ファイルとデータベースを更新できたトラック数 */
	updatedCount: number,
	/**  更新できなかったトラック数（ファイルが見つからない・書き込めないなど） */
	failedCount: number,
	/**  更新できなかったトラックの理由（ファイルごと） */
	errors: string[],
	/**  音楽フォルダの曲を、書式どおりの場所へ移し直した結果（移し直さない場合はnull。ADR-071） */
	organized: KeepOrganizedResult | null,
};

/**  1曲の計画（一覧に表示する） */
export type ConvertEntry = {
	trackId: string,
	/**  元のファイルの名前 */
	sourceName: string,
	/**  出力先（書き出しは、書き出すフォルダからの場所。置き換えは、ファイルの名前。決まらない曲はNone） */
	outputPath: string | null,
	status: ConvertStatus,
	/**  元の曲が可逆の形式か（分からなければNone） */
	sourceLossless: boolean | null,
};

/**  変換先の形式 */
export type ConvertFormat = 
/**  AAC（`.m4a`。非可逆） */
"aac" | 
/**  Apple Lossless（`.m4a`。可逆） */
"alac" | "flac" | "wav" | "aiff";

/**  変換したファイルの出力先 */
export type ConvertMode = 
/**  別のフォルダへ書き出す（ライブラリの曲は変えない） */
"export" | 
/**  元のファイルを置き換える（曲のIDを保ったまま、ファイルと形式を入れ替える） */
"replace";

/**  変換の指定 */
export type ConvertOptions = {
	format: ConvertFormat,
	/**  AACのビットレート（kbps。`AAC_BITRATES_KBPS`のどれか。AACのほかでは使わない） */
	aacBitrateKbps: number,
	mode: ConvertMode,
	/**  書き出す場所の書式（ファイルの整理と同じ書き方。書き出しだけで使う） */
	template: string,
	/**  書き出した曲を、ライブラリに加えるか（書き出しだけで使う） */
	addToLibrary: boolean,
};

/**  変換の計画（選んだ曲の順） */
export type ConvertPlan = {
	entries: ConvertEntry[],
};

/**  形式の変換の進捗 */
export type ConvertProgress = {
	/**  変換が済んだ（失敗した分を含む）曲の数 */
	current: number,
	/**  変換する曲の総数 */
	total: number,
	/**  変換が済んだファイルの名前 */
	currentFile: string,
};

/**  変換の結果 */
export type ConvertResult = {
	/**  変換した曲の数 */
	convertedCount: number,
	/**  変換しなかった曲の数（ファイルが見つからない・出力先がふさがっている） */
	skippedCount: number,
	/**  変換できなかった曲の数 */
	failedCount: number,
	/**  変換できなかった理由（`場所: 理由`） */
	errors: string[],
	/**  途中で中断したか */
	cancelled: boolean,
};

/**  曲を変換するか、変換しない理由 */
