/**  文字列の項目 */
export type TextField = "title" | "artist" | "albumArtist" | "album" | "genre" | 
/**  ファイルの種類（mp3・flacなど） */
"format" | 
/**  ファイルの場所（フォルダ名での絞り込みに使う） */
"path";

/**  文字列の比べ方（大文字と小文字・全角と半角・ひらがなとカタカナは区別しない） */
