/**  値がない（タグがない） */
"isEmpty" | "isNotEmpty";

/**  画面の配色 */
export type Theme = 
/**  ダーク */
"dark" | 
/**  ライト */
"light" | 
/**  OSの設定に従う */
"system";

/**  メニュー「ミニプレーヤー」: ミニプレーヤー（小さな表示）と通常の表示を切り替える */
